# GF-37: event.id is the id of the row pressed, at any depth; cadre.hmi.obasm_items set it on the row
rows = [x for x in self.view.custom.tree.rows if x['id'] == event.id]
if rows:
	r = rows[0]
	if r['action'] == 'alarms' or r['action'] == 'trend':
		self.session.custom.contentNode = r['nodeId']
		system.perspective.navigate('/node/' + r['action'])
	elif r['route']:
		system.perspective.navigate(r['route'])
	if r['deviceId']:
		cadre.hmi.select_device(self.session, r['deviceId'], r['deviceKind'], r['deviceTitle'], r['deviceLabel'], r['tab'], local=r['deviceLocal'])
		if self.session.custom.faceplateMode == 'popup':
			if cadre.hmi.asm_frame(self.session):
				fid = cadre.hmi.float_id(self.session.custom.selectedDevice)
				system.perspective.closePopup(fid)
				system.perspective.openPopup(id=fid, view='Framework/ASM/FloatFaceplate', params=cadre.hmi.float_params(self.session, fid), title=self.session.custom.selectedTitle, position=cadre.hmi.float_position(self.session, self.session.custom.selectedDevice), showCloseIcon=True, draggable=True, resizable=True, modal=False, overlayDismiss=False, viewportBound=True)
			else:
				system.perspective.openPopup(id='faceplatePopup', view='Framework/FaceplatePopup', title=self.session.custom.selectedTitle, position={'top': 56, 'right': 16}, showCloseIcon=True, draggable=True, resizable=True, modal=False, overlayDismiss=False, viewportBound=True)
		else:
			system.perspective.openDock(id='faceplate')
			self.session.custom.faceplateDocked = True
	if r['close'] == 'nav':
		system.perspective.closeDock('nav')
	elif r['close'] == 'search':
		self.session.custom.searchQuery = ''
		self.session.custom.searchOpen = False
	elif r['close']:
		system.perspective.closePopup(r['close'])

